import sailpoint.object.*;
import sailpoint.object.ProvisioningPlan.AccountRequest;
import javax.naming.*;
import javax.naming.ldap.*;
import java.util.*;

if (plan != null) {
    List accountRequests = plan.getAccountRequests();
    if (accountRequests != null) {
        for (AccountRequest acctReq : accountRequests) {
            if ("OpenLDAP".equals(acctReq.getApplicationName()) &&
                AccountRequest.Operation.Disable.equals(acctReq.getOperation())) {

                String currentDN = acctReq.getNativeIdentity();
                if (currentDN != null) {
                    String targetOU = "ou=disabled,dc=example,dc=com";
                    String rdn = currentDN.substring(0, currentDN.indexOf(","));
                    String newDN = rdn + "," + targetOU;

                    try {
                        Application app = context.getObjectByName(
                        Application.class, "OpenLDAP");

                    String host = (String) app.getAttributeValue("host");
                    String port = (String) app.getAttributeValue("port");
                    boolean useSSL = "true".equals(String.valueOf(app.getAttributeValue("useSSL")));
                    String protocol = useSSL ? "ldaps" : "ldap";
                    String ldapUrl = protocol + "://" + host + ":" + port;

                    String bindDN = (String) app.getAttributeValue("user");
                    String bindPw = (String) app.getAttributeValue("password");

                    log.debug("Connecting to: " + ldapUrl + " as " + bindDN);

                    Hashtable env = new Hashtable();
                    env.put(Context.INITIAL_CONTEXT_FACTORY,
                        "com.sun.jndi.ldap.LdapCtxFactory");
                    env.put(Context.PROVIDER_URL, ldapUrl);
                    env.put(Context.SECURITY_AUTHENTICATION, "simple");
                    env.put(Context.SECURITY_PRINCIPAL, bindDN);
                    env.put(Context.SECURITY_CREDENTIALS,
                        context.decrypt(bindPw));

                        LdapContext ldapCtx = new InitialLdapContext(env, null);
                        ldapCtx.rename(currentDN, newDN);
                        ldapCtx.close();

                        acctReq.setNativeIdentity(newDN);
                        log.debug("Moved " + currentDN + " to " + newDN);
                    } catch (NamingException e) {
                        log.error("Failed to move LDAP entry: " + e.getMessage());
                    }
                }
            }
        }
    }
}
